#include "PluginEditor.h"

#include <BinaryData.h> // generated by juce_add_binary_data (namespace SpikeUI)

namespace
{
juce::String mimeFor (const juce::String& filename)
{
    if (filename.endsWithIgnoreCase (".html")) return "text/html";
    if (filename.endsWithIgnoreCase (".js"))   return "text/javascript";
    if (filename.endsWithIgnoreCase (".css"))  return "text/css";
    if (filename.endsWithIgnoreCase (".svg"))  return "image/svg+xml";
    return "application/octet-stream";
}

// WebView2 needs a writable folder for its cache. By default it would try the host's install
// folder (e.g. C:\Program Files\Image-Line\...), which is read-only, and the UI would stay blank.
juce::File webViewDataFolder()
{
    return juce::File::getSpecialLocation (juce::File::tempDirectory).getChildFile ("FourierizerSpike-WebView2");
}
} // namespace

PluginEditor::PluginEditor (PluginProcessor& p)
    : AudioProcessorEditor (&p),
      processorRef (p),
      webView (juce::WebBrowserComponent::Options {}
                   .withBackend (juce::WebBrowserComponent::Options::Backend::webview2)
                   .withWinWebView2Options (juce::WebBrowserComponent::Options::WinWebView2 {}
                                                .withUserDataFolder (webViewDataFolder()))
                   .withNativeIntegrationEnabled()
                   .withResourceProvider ([this] (const auto& url) { return getResource (url); })
                   .withOptionsFrom (gainRelay)
                   .withNativeFunction ("getHostInfo",
                                        [this] (const juce::Array<juce::var>&, auto complete)
                                        { complete (getHostInfo()); })),
      gainAttachment (*processorRef.parameters.getParameter ("gain"), gainRelay, nullptr)
{
    addAndMakeVisible (webView);
    webView.goToURL (juce::WebBrowserComponent::getResourceProviderRoot());

    setResizable (true, true);
    setResizeLimits (480, 360, 1600, 1200);
    setSize (720, 480);

    startTimerHz (30); // push meter values to the UI ~30 times per second
}

PluginEditor::~PluginEditor()
{
    stopTimer();
}

void PluginEditor::resized()
{
    webView.setBounds (getLocalBounds());
}

void PluginEditor::timerCallback()
{
    auto* obj = new juce::DynamicObject();
    obj->setProperty ("rms", processorRef.getSidechainRms());
    obj->setProperty ("channels", processorRef.getSidechainChannels());
    obj->setProperty ("voices", processorRef.getActiveVoices());
    webView.emitEventIfBrowserIsVisible ("meters", juce::var (obj));
}

juce::var PluginEditor::getHostInfo() const
{
    auto* obj = new juce::DynamicObject();
    obj->setProperty ("host", juce::PluginHostType().getHostDescription());
    obj->setProperty ("format", juce::AudioProcessor::getWrapperTypeDescription (processorRef.wrapperType));
    obj->setProperty ("sampleRate", processorRef.getSampleRate());
    obj->setProperty ("blockSize", processorRef.getBlockSize());
    obj->setProperty ("version", JucePlugin_VersionString);
    obj->setProperty ("juce", juce::SystemStats::getJUCEVersion());
    return juce::var (obj);
}

std::optional<juce::WebBrowserComponent::Resource> PluginEditor::getResource (const juce::String& url) const
{
    // url is the path after the resource-provider root, e.g. "/", "/main.js", "/juce/index.js".
    auto path = url.upToFirstOccurrenceOf ("?", false, false);
    if (path.isEmpty() || path == "/")
        path = "/index.html";
    const auto filename = path.fromLastOccurrenceOf ("/", false, false);

    for (int i = 0; i < SpikeUI::namedResourceListSize; ++i)
    {
        if (filename != SpikeUI::originalFilenames[i])
            continue;

        int size = 0;
        if (const auto* bytes = SpikeUI::getNamedResource (SpikeUI::namedResourceList[i], size))
        {
            const auto* begin = reinterpret_cast<const std::byte*> (bytes);
            return juce::WebBrowserComponent::Resource { std::vector<std::byte> (begin, begin + size), mimeFor (filename) };
        }
    }
    return std::nullopt;
}
